package agent

// catalogue holds Windows diagnostics and repairs. PowerShell unless noted.
var catalogue = []action{
	def("systeminfo", "Full systeminfo report (OS, hotfixes, boot time)", "systeminfo", shell("cmd")),
	def("event-errors", "Critical and error events from System and Application, last 48h",
		`Get-WinEvent -FilterHashtable @{LogName='System','Application';Level=1,2;StartTime=(Get-Date).AddDays(-2)} -MaxEvents 150 -ErrorAction SilentlyContinue | Format-Table TimeCreated,LogName,ProviderName,Id,LevelDisplayName,Message -AutoSize -Wrap | Out-String -Width 240`),
	def("crash-history", "Bugchecks (BSOD), unexpected shutdowns and minidumps",
		`Get-WinEvent -FilterHashtable @{LogName='System';Id=41,1001,6008} -MaxEvents 30 -ErrorAction SilentlyContinue | Format-Table TimeCreated,Id,ProviderName,Message -AutoSize -Wrap | Out-String -Width 240; Get-ChildItem "$env:SystemRoot\Minidump" -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Format-Table Name,Length,LastWriteTime`),
	def("reliability", "Reliability Monitor records, last 14 days",
		`Get-CimInstance Win32_ReliabilityRecords -ErrorAction SilentlyContinue | Where-Object { $_.TimeGenerated -gt (Get-Date).AddDays(-14) } | Sort-Object TimeGenerated -Descending | Select-Object -First 60 TimeGenerated,SourceName,ProductName,Message | Format-Table -AutoSize -Wrap | Out-String -Width 240`, slow),
	def("sfc-scan", "System File Checker: scan and repair protected system files", "sfc /scannow", shell("cmd"), slow),
	def("dism-scan", "DISM: scan the component store for corruption", "DISM /Online /Cleanup-Image /ScanHealth", shell("cmd"), slow),
	def("dism-restore", "DISM: repair the component store from Windows Update", "DISM /Online /Cleanup-Image /RestoreHealth", shell("cmd"), slow),
	def("chkdsk-scan", "Online chkdsk scan of a volume (read-only, no reboot)", "chkdsk {{1}} /scan", shell("cmd"), params("drive"), slow),
	def("disk-health", "Physical disk health and SMART-style reliability counters",
		`Get-PhysicalDisk | Format-Table FriendlyName,MediaType,BusType,HealthStatus,OperationalStatus,@{n='SizeGB';e={[math]::Round($_.Size/1GB)}} -AutoSize; Get-PhysicalDisk | Get-StorageReliabilityCounter -ErrorAction SilentlyContinue | Format-Table DeviceId,Temperature,Wear,PowerOnHours,ReadErrorsTotal,WriteErrorsTotal -AutoSize`),
	def("device-problems", "Devices with driver or hardware problems",
		`Get-PnpDevice -PresentOnly | Where-Object Status -ne 'OK' | Format-Table Status,Class,FriendlyName,InstanceId -AutoSize -Wrap | Out-String -Width 240`),
	def("drivers", "Installed third-party drivers",
		`Get-CimInstance Win32_PnPSignedDriver | Where-Object { $_.DriverProviderName -and $_.DriverProviderName -ne 'Microsoft' } | Sort-Object DeviceClass | Format-Table DeviceClass,DeviceName,DriverProviderName,DriverVersion,DriverDate -AutoSize | Out-String -Width 240`),
	def("services-stopped", "Automatic services that are not running",
		`Get-CimInstance Win32_Service -Filter "StartMode='Auto' AND State<>'Running'" | Format-Table Name,DisplayName,State,ExitCode -AutoSize`),
	def("restart-service", "Restart a Windows service by name", `Restart-Service -Name {{1}} -Force -PassThru | Format-Table Name,Status`, params("service")),
	def("startup-items", "Programs that start with Windows",
		`Get-CimInstance Win32_StartupCommand | Format-Table Name,Command,Location,User -AutoSize -Wrap | Out-String -Width 240`),
	def("installed-apps", "Installed applications (machine and current-user uninstall keys)",
		`Get-ItemProperty 'HKLM:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*','HKLM:\Software\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*' -ErrorAction SilentlyContinue | Where-Object DisplayName | Sort-Object DisplayName | Format-Table DisplayName,DisplayVersion,Publisher,InstallDate -AutoSize | Out-String -Width 240`),
	def("updates", "Most recently installed updates", `Get-HotFix | Sort-Object InstalledOn -Descending | Select-Object -First 25 | Format-Table HotFixID,Description,InstalledOn -AutoSize`),
	def("net-diag", "Adapters, IP config, DNS and reachability",
		`Get-NetAdapter | Format-Table Name,InterfaceDescription,Status,LinkSpeed,MacAddress -AutoSize; Get-NetIPConfiguration | Format-List InterfaceAlias,IPv4Address,IPv4DefaultGateway,DNSServer; Test-NetConnection 1.1.1.1 | Format-List ComputerName,PingSucceeded,PingReplyDetails; Resolve-DnsName example.com -ErrorAction SilentlyContinue | Format-Table -AutoSize`),
	def("flush-dns", "Flush the DNS resolver cache", "ipconfig /flushdns", shell("cmd")),
	def("network-reset", "Reset Winsock and the TCP/IP stack (needs a reboot; may drop the session)",
		"netsh winsock reset & netsh int ip reset & ipconfig /flushdns", shell("cmd"), dangerous),
	def("battery-report", "Generate a battery report in C:\\Windows\\Temp (pull it afterwards)",
		`powercfg /batteryreport /output C:\Windows\Temp\battery-report.html`, shell("cmd")),
	def("energy-report", "60s power efficiency trace into C:\\Windows\\Temp", `powercfg /energy /output C:\Windows\Temp\energy-report.html`, shell("cmd"), slow),
	def("defender-status", "Microsoft Defender status and recent threats",
		`Get-MpComputerStatus | Format-List AMRunningMode,RealTimeProtectionEnabled,AntivirusSignatureLastUpdated,QuickScanEndTime; Get-MpThreatDetection | Select-Object -First 20 | Format-Table InitialDetectionTime,ThreatID,Resources -AutoSize -Wrap`),
	def("defender-quick-scan", "Run a Microsoft Defender quick scan", "Start-MpScan -ScanType QuickScan; 'scan finished'", slow),
	def("temp-usage", "Size of temp folders", `foreach($p in @("$env:SystemRoot\Temp","C:\Users\*\AppData\Local\Temp")){ Get-Item $p -ErrorAction SilentlyContinue | ForEach-Object { '{0,10:N0} MB  {1}' -f ((Get-ChildItem $_ -Recurse -Force -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum/1MB), $_.FullName } }`, slow),
	def("clear-temp", "Delete temp files older than 2 days (system and all users)",
		`foreach($p in @("$env:SystemRoot\Temp","C:\Users\*\AppData\Local\Temp")){ Get-ChildItem $p -Recurse -Force -ErrorAction SilentlyContinue | Where-Object { -not $_.PSIsContainer -and $_.LastWriteTime -lt (Get-Date).AddDays(-2) } | Remove-Item -Force -ErrorAction SilentlyContinue }; 'done'`, dangerous, slow),
	def("reboot", "Reboot in 30 seconds", `shutdown /r /t 30 /c "Rebooting for maintenance"`, shell("cmd"), dangerous),
	def("shutdown", "Shut down in 30 seconds", `shutdown /s /t 30 /c "Shutting down for maintenance"`, shell("cmd"), dangerous),
	def("cancel-shutdown", "Cancel a pending reboot or shutdown", "shutdown /a", shell("cmd")),
}
